require_once __DIR__ . '/config.php';
header('Content-Type: text/html; charset=utf-8');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AURA Sensor Simulator</title><style>body{font-family:Arial;background:#f4f7f5;margin:0;padding:30px}.box{max-width:700px;margin:auto;background:#fff;padding:25px;border-radius:16px;box-shadow:0 8px 30px #0001}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{font-weight:700}input,select,button{width:100%;box-sizing:border-box;padding:11px;margin-top:5px}button{cursor:pointer;border:0;border-radius:8px;background:#198754;color:#fff;font-weight:700}.row{margin-top:16px}.status{padding:12px;background:#eef5f0;border-radius:8px;white-space:pre-wrap}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><div class="box"><h1>🌾 AURA Sensor Simulator</h1><p>Inject test readings directly into MariaDB through the same API used by ESP8266.</p><div class="grid"><label>Temperature °C<input id="temperature" type="number" step="0.1" value="28.5"></label><label>Humidity %<input id="humidity" type="number" step="0.1" value="65"></label><label>Moisture %<input id="moisture_pct" type="number" step="0.1" value="42"></label><label>Capacity %<input id="capacity_pct" type="number" step="0.1" value="70"></label><label>Ultrasonic 1 cm<input id="ultrasonic1_cm" type="number" step="0.1" value="30"></label><label>Ultrasonic 2 cm<input id="ultrasonic2_cm" type="number" step="0.1" value="25"></label><label>Fire<select id="fire_detected"><option value="0">No</option><option value="1">Yes</option></select></label><label>Motor<select id="motor_on"><option value="0">OFF</option><option value="1">ON</option></select></label></div><div class="row"><button id="inject">Inject once</button></div><div class="row"><button id="toggle">Start automatic simulation</button></div><div class="row status" id="status">Ready.</div></div><script>const ids=['temperature','humidity','moisture_pct','capacity_pct','ultrasonic1_cm','ultrasonic2_cm','fire_detected','motor_on'];let timer=null;function payload(){const o={};ids.forEach(id=>o[id]=document.getElementById(id).value);return o}async function inject(){const r=await fetch('data_insert.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload())});const j=await r.json();document.getElementById('status').textContent=JSON.stringify(j,null,2)}document.getElementById('inject').onclick=inject;document.getElementById('toggle').onclick=(e)=>{if(timer){clearInterval(timer);timer=null;e.currentTarget.textContent='Start automatic simulation';return}timer=setInterval(()=>{const t=26+Math.random()*10,h=50+Math.random()*30,m=Math.max(5,Math.min(95,Number(document.getElementById('moisture_pct').value)+(Math.random()*6-3)));document.getElementById('temperature').value=t.toFixed(1);document.getElementById('humidity').value=h.toFixed(1);document.getElementById('moisture_pct').value=m.toFixed(1);inject()},5000);e.currentTarget.textContent='Stop automatic simulation';inject()};</script></body></html>
